// Auto-generated default vehicle image base64
export const DEFAULT_VEHICLE_IMAGE_BASE64 = "";

export const getVehicleImageSource = (base64String?: string | null) => {
  if (!base64String || base64String === DEFAULT_VEHICLE_IMAGE_BASE64 || base64String.trim() === '') {
    console.log('📷 [getVehicleImageSource] Returning default vehicle image');
    return require('../../assets/vehicle_hero_saffron.png');
  }
  const cleanString = base64String.replace(/[\r\n]+/g, '').trim();
  if (cleanString.startsWith('http') || cleanString.startsWith('https') || cleanString.startsWith('data:image')) {
    console.log(`📷 [getVehicleImageSource] Returning URI format (length: ${cleanString.length})`);
    return { uri: cleanString };
  }
  console.log(`📷 [getVehicleImageSource] Appending data:image/jpeg;base64, (length: ${cleanString.length})`);
  return { uri: `data:image/jpeg;base64,${cleanString}` };
};

